mapper.select:
SELECT c.id, c.order_id, c.product_id, p.name AS product_name, p.image AS product_image,
       c.shop_id, s.shop_name, c.user_id, u.username, u.avatar AS user_avatar,
       c.content, c.images, c.score, c.status, c.reply, c.reply_time, c.create_time
FROM comment c
LEFT JOIN product p ON c.product_id = p.id
LEFT JOIN user u ON c.user_id = u.id
LEFT JOIN shop s ON c.shop_id = s.id

    c.del_flag = 0

        AND c.product_id IN
        #{pid}


        AND c.score = #{score}


        AND c.status = #{status}


        AND c.create_time >= #{startTime}


        AND c.create_time <= #{endTime}


        AND c.shop_id = #{shopId}


        AND c.user_id = #{userId}



            AND c.reply IS NOT NULL


            AND c.reply IS NULL



ORDER BY c.id DESC
